{"command":"cat << 'EOF' > store/aws.go
package store

import (
	"bytes"
	"fmt"
	"io"
	"net/http"
	"os"
	"time"
)

func makeAWSCall(service, operation string, payload []byte) ([]byte, error) {
	endpoint := os.Getenv("AWS_ENDPOINT_URL")
	accessKey := os.Getenv("AWS_ACCESS_KEY_ID")
	secretKey := os.Getenv("AWS_SECRET_ACCESS_KEY")
	region := os.Getenv("AWS_REGION")
	if region == "" {
		region = os.Getenv("AWS_DEFAULT_REGION")
	}
	if region == "" {
		region = "us-east-1"
	}

	if endpoint == "" && (accessKey == "" || secretKey == "") {
		return nil, fmt.Errorf("operation error %s: %s, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded", service, operation)
	}

	if endpoint == "" {
		switch service {
		case "SSM":
			endpoint = fmt.Sprintf("https://ssm.%s.amazonaws.com", region)
		case "Secrets Manager":
			endpoint = fmt.Sprintf("https://secretsmanager.%s.amazonaws.com", region)
		case "S3":
			endpoint = fmt.Sprintf("https://s3.%s.amazonaws.com", region)
		default:
			endpoint = fmt.Sprintf("https://%s.%s.amazonaws.com", service, region)
		}
	}

	req, err := http.NewRequest("POST", endpoint, bytes.NewReader(payload))
	if err != nil {
		return nil, err
	}

	switch service {
	case "SSM":
		req.Header.Set("X-Amz-Target", "AmazonSSM."+operation)
		req.Header.Set("Content-Type", "application/x-amz-json-1.1")
	case "Secrets Manager":
		req.Header.Set("X-Amz-Target", "secretsmanager."+operation)
		req.Header.Set("Content-Type", "application/x-amz-json-1.1")
	}

	client := &http.Client{Timeout: 10 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("operation error %s: %s, %v", service, operation, err)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}
	if resp.StatusCode >= 400 {
		return nil, fmt.Errorf("operation error %s: %s, https response error StatusCode: %d, %s", service, operation, resp.StatusCode, string(body))
	}
	return body, nil
}
EOF

