{"command":"cat << 'EOF' > cmd/root.go
package cmd

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/segmentio/chamber/store"
	"github.com/spf13/cobra"
)

var (
	backend         string
	backendS3Bucket string
	kmsKeyAlias     string
	retries         int
	retryMode       string
	verbose         bool
)

var rootCmd = &cobra.Command{
	Use:   "chamber",
	Short: "CLI for storing secrets",
	Long:  "CLI for storing secrets",
}

func Execute() {
	if err := rootCmd.Execute(); err != nil {
		os.Exit(1)
	}
}

func init() {
	rootCmd.PersistentFlags().StringVarP(&backend, "backend", "b", "ssm", "Backend to use; AKA $CHAMBER_SECRET_BACKEND\n\tnull: no-op\n\tssm: SSM Parameter Store\n\tsecretsmanager: Secrets Manager\n\ts3: S3; requires --backend-s3-bucket\n\ts3-kms: S3 using AWS-KMS encryption; requires --backend-s3-bucket and --kms-key-alias set (if you want to write or delete keys).")
	rootCmd.PersistentFlags().StringVar(&backendS3Bucket, "backend-s3-bucket", "", "bucket for S3 backend; AKA $CHAMBER_S3_BUCKET")
	rootCmd.PersistentFlags().StringVar(&kmsKeyAlias, "kms-key-alias", "alias/parameter_store_key", "KMS Key Alias for writing and deleting secrets; AKA $CHAMBER_KMS_KEY_ALIAS. This option is currently only supported for the S3-KMS backend.")
	rootCmd.PersistentFlags().IntVarP(&retries, "retries", "r", 10, "For SSM or Secrets Manager, the number of retries we'll make before giving up; AKA $CHAMBER_RETRIES")
	rootCmd.PersistentFlags().StringVar(&retryMode, "retry-mode", "standard", "For SSM, the model used to retry requests\n  standard\n  adaptive")
	rootCmd.PersistentFlags().BoolVar(&verbose, "verbose", false, "Print more information to STDERR")
}

func getStore(cmd *cobra.Command) (store.Store, error) {
	b := backend
	if !cmd.Flags().Changed("backend") {
		if envB := os.Getenv("CHAMBER_SECRET_BACKEND"); envB != "" {
			b = envB
		}
	}

	s3B := backendS3Bucket
	if !cmd.Flags().Changed("backend-s3-bucket") {
		if envS3 := os.Getenv("CHAMBER_S3_BUCKET"); envS3 != "" {
			s3B = envS3
		}
	}

	kms := kmsKeyAlias
	if !cmd.Flags().Changed("kms-key-alias") {
		if envKms := os.Getenv("CHAMBER_KMS_KEY_ALIAS"); envKms != "" {
			kms = envKms
		}
	}

	r := retries
	if !cmd.Flags().Changed("retries") {
		if envR := os.Getenv("CHAMBER_RETRIES"); envR != "" {
			if parsed, err := strconv.Atoi(envR); err == nil {
				r = parsed
			}
		}
	}

	s, err := store.GetSecretStore(b, s3B, kms, r, retryMode)
	if err != nil {
		return nil, fmt.Errorf("Failed to get secret store: %v", err)
	}
	return s, nil
}
EOF"}

