package cmd

import (
	"io"
	"os"
	"strings"

	"github.com/segmentio/chamber/store"
	"github.com/spf13/cobra"
)

var (
	singleline    bool
	skipUnchanged bool
	tags          map[string]string
)

var writeCmd = &cobra.Command{
	Use:   "write <service> <key> [--] <value|->",
	Short: "write a secret",
	Args:  cobra.ExactArgs(3),
	RunE: func(cmd *cobra.Command, args []string) error {
		service := args[0]
		key := strings.ToLower(args[1])
		val := args[2]

		if val == "-" {
			data, err := io.ReadAll(os.Stdin)
			if err != nil {
				return err
			}
			val = string(data)
		}

		if singleline {
			if !strings.HasSuffix(val, "\n") {
				val += "\n"
			}
		}

		s, err := getStore(cmd)
		if err != nil {
			return err
		}

		if skipUnchanged {
			existing, err := s.Read(service, key)
			if err == nil && existing.Value == val {
				return nil
			}
		}

		sec := store.Secret{
			Key:   key,
			Value: val,
		}

		if len(tags) > 0 {
			err = s.WriteWithTags(sec, true, tags)
		} else {
			err = s.Write(sec, true)
		}

		if err != nil {
			return err
		}
		return nil
	},
}

