			}
			if !foundDash {
				if strings.HasPrefix(arg, "-") || arg == "./executable" || arg == "chamber" || arg == "exec" {
					continue
				}
				services = append(services, arg)
			} else {
				execCmdAndArgs = append(execCmdAndArgs, arg)
			}
		}

		if len(services) == 0 {
			return fmt.Errorf("at least one service must be specified: requires at least 1 arg(s), only received 0")
		}
		if len(execCmdAndArgs) == 0 {
			return fmt.Errorf("must specify command to run. See usage: requires at least 1 arg(s), only received 0")
		}

		s, err := getStore(cmd)
		if err != nil {
			return err
		}

		secretMap := make(map[string]string)
		for _, svc := range services {
			secs, err := s.List(svc)
			if err != nil {
				return fmt.Errorf("Failed to list store contents: %v", err)
			}
			for _, sec := range secs {
				envKey := strings.ToUpper(sec.Key)
				secretMap[envKey] = sec.Value
			}
		}

		if strict {
			for _, envKV := range os.Environ() {
				parts := strings.SplitN(envKV, "=", 2)
				if len(parts) == 2 {
					if parts[1] == strictValue {
						if _, exists := secretMap[parts[0]]; !exists {
							return fmt.Errorf("parent env was expecting %s=%s, but was not in store", parts[0], strictValue)
						}
					}
				}
			}
		}

		var envList []string
		if pristine {
			for k, v := range secretMap {
				envList = append(envList, fmt.Sprintf("%s=%s", k, v))
			}
		} else {
			envKVMap := make(map[string]string)
			for _, envKV := range os.Environ() {
				parts := strings.SplitN(envKV, "=", 2)
				if len(parts) == 2 {
					envKVMap[parts[0]] = parts[1]
				}
			}
			for k, v := range secretMap {
				envKVMap[k] = v
			}
			for k, v := range envKVMap {
				envList = append(envList, fmt.Sprintf("%s=%s", k, v))
			}
		}

		binary, err := exec.LookPath(execCmdAndArgs[0])
		if err != nil {
			return fmt.Errorf("failed to find executable %s: %v", execCmdAndArgs[0], err)
		}

		return syscall.Exec(binary, execCmdAndArgs, envList)
	},
}

func init() {
	execCmd.Flags().BoolVar(&pristine, "pristine", false, "only use variables retrieved from the backend; do not inherit existing environment variables")
	execCmd.Flags().BoolVar(&strict, "strict", false, "enable strict mode:\nonly inject secrets for which there is a corresponding env var with value\n<strict-value>, and fail if there are any env vars with that value missing\nfrom secrets")
	execCmd.Flags().StringVar(&strictValue, "strict-value", "chamberme", "value to expect in --strict mode")
	rootCmd.AddCommand(execCmd)
}
EOF"}

