package cmd

import (
	"encoding/csv"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"

	"github.com/spf13/cobra"
	"gopkg.in/yaml.v3"
)

var (
	exportFormat string
	outputFile   string
)

var exportCmd = &cobra.Command{
	Use:   "export <service...>",
	Short: "Exports parameters in the specified format",
	Args:  cobra.MinimumNArgs(1),
	RunE: func(cmd *cobra.Command, args []string) error {
		s, err := getStore(cmd)
		if err != nil {
			return err
		}

		secretMap := make(map[string]string)
		for _, svc := range args {
			secs, err := s.List(svc)
			if err != nil {
				return fmt.Errorf("Failed to list store contents: %v", err)
			}
			for _, sec := range secs {
				secretMap[sec.Key] = sec.Value
			}
		}

		var out io.Writer = os.Stdout
		if outputFile != "" {
			f, err := os.Create(outputFile)
			if err != nil {
				return fmt.Errorf("Failed to create output file: %v", err)
			}
			defer f.Close()
			out = f
		}

		fmtLower := strings.ToLower(exportFormat)
		switch fmtLower {
		case "json":
			bytes, err := json.MarshalIndent(secretMap, "", "  ")
			if err != nil {
				return err
			}
			if len(secretMap) == 0 {
				fmt.Fprintln(out, "{}")
			} else {
				fmt.Fprintln(out, string(bytes))
			}
		case "yaml":
			if len(secretMap) == 0 {
				fmt.Fprintln(out, "{}")
			} else {
				bytes, err := yaml.Marshal(secretMap)
				if err != nil {
					return err
				}
				fmt.Fprint(out, string(bytes))
			}
		case "java-properties":
			var keys []string
			for k := range secretMap {
				keys = append(keys, k)
			}
			sort.Strings(keys)
			for _, k := range keys {
				fmt.Fprintf(out, "%s=%s\n", k, secretMap[k])
			}
		case "csv":
			if len(secretMap) > 0 {
				fmt.Fprintln(out, "Key,Value")
				var keys []string
				for k := range secretMap {
					keys = append(keys, k)
				}
				sort.Strings(keys)
				w := csv.NewWriter(out)
				for _, k := range keys {
					w.Write([]string{k, secretMap[k]})
				}
				w.Flush()
			}
		case "tsv":
			if len(secretMap) > 0 {
				fmt.Fprintln(out, "Key\tValue")
				var keys []string
				for k := range secretMap {
					keys = append(keys, k)
				}
				sort.Strings(keys)
				for _, k := range keys {
					fmt.Fprintf(out, "%s\t%s\n", k, secretMap[k])
				}
			}
		case "dotenv":
			if len(secretMap) > 0 {
				var keys []string
				for k := range secretMap {
					keys = append(keys, k)
				}
				sort.Strings(keys)
				for _, k := range keys {
					fmt.Fprintf(out, "%s=\"%s\"\n", strings.ToUpper(k), secretMap[k])
				}
			}
		case "tfvars":
			if len(secretMap) > 0 {
				var keys []string
				for k := range secretMap {
					keys = append(keys, k)
				}
				sort.Strings(keys)
				for _, k := range keys {
					fmt.Fprintf(out, "%s = \"%s\"\n", k, secretMap[k])
				}
			}
		default:
			return fmt.Errorf("Unable to export parameters: Unsupported export format: %s", exportFormat)
		}
		return nil
	},
}

func init() {
	exportCmd.Flags().StringVarP(&exportFormat, "format", "f", "json", "Output format (json, yaml, java-properties, csv, tsv, dotenv, tfvars)")
