package cmd

import (
	"fmt"
	"os"
	"strings"
	"text/tabwriter"

	"github.com/spf13/cobra"
)

var findByValue bool

var findCmd = &cobra.Command{
	Use:   "find <secret name>",
	Short: "Find the given secret across all services",
	Args:  cobra.ExactArgs(1),
	RunE: func(cmd *cobra.Command, args []string) error {
		target := args[0]

		s, err := getStore(cmd)
		if err != nil {
			return err
		}

		services, err := s.ListServices()
		if err != nil {
			return fmt.Errorf("Failed to list services: %v", err)
		}

		w := tabwriter.NewWriter(os.Stdout, 0, 8, 2, '\t', 0)
		if findByValue {
			fmt.Fprintln(w, "Service\t\tKey")
			for _, svc := range services {
				secrets, err := s.List(svc)
				if err != nil {
					continue
				}
				for _, sec := range secrets {
					if sec.Value == target {
						fmt.Fprintf(w, "%s\t\t%s\n", svc, sec.Key)
					}
				}
			}
		} else {
			fmt.Fprintln(w, "Service")
			targetLower := strings.ToLower(target)
			for _, svc := range services {
				secrets, err := s.List(svc)
				if err != nil {
					continue
				}
				for _, sec := range secrets {
					if strings.ToLower(sec.Key) == targetLower {
						fmt.Fprintln(w, svc)
						break
					}
				}
			}
		}
		return w.Flush()
	},
}

func init() {
	findCmd.Flags().BoolVarP(&findByValue, "by-value", "v", false, "Find parameters by value")
	rootCmd.AddCommand(findCmd)
}
EOF

