import (
	"fmt"
	"strings"
	"time"
)

type Secret struct {
	Service      string
	Key          string
	Value        string
	Version      int
	LastModified time.Time
	User         string
}

type Change struct {
	Type    string
	Version int
	Date    time.Time
	User    string
}

type Store interface {
	Write(secret Secret, force bool) error
	WriteWithTags(secret Secret, force bool, tags map[string]string) error
	Read(service string, key string, version int) (Secret, error)
	List(service string) ([]Secret, error)
	ListServices() ([]string, error)
	Delete(service string, key string) error
	History(service string, key string) ([]Change, error)
	GetTags(service string, key string) (map[string]string, error)
	SetTags(service string, key string, tags map[string]string, deleteOthers bool) error
	DeleteTags(service string, key string, tagKeys []string) error
}

func GetSecretStore(backend, s3Bucket, kmsKeyAlias string, retries int, retryMode string) (Store, error) {
	b := strings.ToLower(backend)
	switch b {
	case "null":
		return &NullStore{}, nil
	case "ssm":
		return NewSSMStore(kmsKeyAlias, retries, retryMode), nil
	case "secretsmanager":
		return NewSecretsManagerStore(kmsKeyAlias, retries), nil
	case "s3":
		if s3Bucket == "" {
			return nil, fmt.Errorf("Must set bucket for s3 backend")
		}
		return NewS3Store(s3Bucket, kmsKeyAlias), nil
	case "s3-kms":
		if s3Bucket == "" {
			return nil, fmt.Errorf("Must set bucket for s3 backend")
		}
		return NewS3KMSStore(s3Bucket, kmsKeyAlias), nil
	default:
		return nil, fmt.Errorf("invalid backend `%s`", strings.ToUpper(backend))
	}
}
EOF

