cat << 'EOF' > cmd/import.go
package cmd

import (
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/segmentio/chamber/store"
	"github.com/spf13/cobra"
	"gopkg.in/yaml.v3"
)

var normalizeKeys bool

var importCmd = &cobra.Command{
	Use:   "import <service> <file|->",
	Short: "import secrets from json or yaml",
	Args:  cobra.ExactArgs(2),
	RunE: func(cmd *cobra.Command, args []string) error {
		service := args[0]
		filePath := args[1]

		var data []byte
		var err error
		if filePath == "-" {
			data, err = io.ReadAll(os.Stdin)
		} else {
			data, err = os.ReadFile(filePath)
		}
		if err != nil {
			return fmt.Errorf("Failed to read input file: %v", err)
		}

		secretMap := make(map[string]interface{})
		err = yaml.Unmarshal(data, &secretMap)
		if err != nil {
			return fmt.Errorf("Failed to decode input as json: %v", err)
		}

		s, err := getStore(cmd)
		if err != nil {
			return err
		}

		for k, v := range secretMap {
			key := k
			if normalizeKeys {
				key = strings.ToLower(key)
			}
			val := fmt.Sprintf("%v", v)
			sec := store.Secret{
				Service: service,
				Key:     key,
				Value:   val,
			}
			if err := s.Write(sec, true); err != nil {
				return fmt.Errorf("Failed to write secret: %v", err)
			}
		}
		return nil
	},
}

func init() {
	importCmd.Flags().BoolVar(&normalizeKeys, "normalize-keys", false, "Normalize keys to match how chamber write would handle them. If not specified, keys will be written exactly how they are defined in the import source.")
	rootCmd.AddCommand(importCmd)
}
EOF"}

