{"command":"cat << 'EOF' > cmd/list.go
package cmd

import (
	"fmt"
	"os"
	"sort"
	"text/tabwriter"
	"time"

	"github.com/spf13/cobra"
)

var (
	expand        bool
	sortByTime    bool
	sortByUser    bool
	sortByVersion bool
)

var listCmd = &cobra.Command{
	Use:   "list <service>",
	Short: "List the secrets set for a service",
	Args:  cobra.ExactArgs(1),
	RunE: func(cmd *cobra.Command, args []string) error {
		service := args[0]

		s, err := getStore(cmd)
		if err != nil {
			return err
		}

		secrets, err := s.List(service)
		if err != nil {
			return fmt.Errorf("Failed to list store contents: %v", err)
		}

		if sortByTime {
			sort.Slice(secrets, func(i, j int) bool {
				return secrets[i].LastModified.Before(secrets[j].LastModified)
			})
		} else if sortByUser {
			sort.Slice(secrets, func(i, j int) bool {
				return secrets[i].User < secrets[j].User
			})
		} else if sortByVersion {
			sort.Slice(secrets, func(i, j int) bool {
				return secrets[i].Version < secrets[j].Version
			})
		} else {
			sort.Slice(secrets, func(i, j int) bool {
				return secrets[i].Key < secrets[j].Key
			})
		}

		if expand {
			fmt.Fprintln(os.Stdout, "Key\tVersion\t\tLastModified\tUser\tValue")
			if len(secrets) > 0 {
				w := tabwriter.NewWriter(os.Stdout, 0, 8, 2, '\t', 0)
				for _, sec := range secrets {
					fmt.Fprintf(w, "%s\t%d\t\t%s\t%s\t%s\n", sec.Key, sec.Version, sec.LastModified.Format(time.RFC3339), sec.User, sec.Value)
				}
				w.Flush()
			}
		} else {
			fmt.Fprintln(os.Stdout, "Key\tVersion\t\tLastModified\tUser")
			if len(secrets) > 0 {
				w := tabwriter.NewWriter(os.Stdout, 0, 8, 2, '\t', 0)
				for _, sec := range secrets {
					fmt.Fprintf(w, "%s\t%d\t\t%s\t%s\n", sec.Key, sec.Version, sec.LastModified.Format(time.RFC3339), sec.User)
				}
				w.Flush()
			}
		}
		return nil
	},
}

func init() {
	listCmd.Flags().BoolVarP(&expand, "expand", "e", false, "Expand parameter list with values")
	listCmd.Flags().BoolVarP(&sortByTime, "time", "t", false, "Sort by modified time")
	listCmd.Flags().BoolVarP(&sortByUser, "user", "u", false, "Sort by user")
	listCmd.Flags().BoolVarP(&sortByVersion, "version", "v", false, "Sort by version")
	rootCmd.AddCommand(listCmd)
}
