import (
	"fmt"
	"os"
	"sort"
	"text/tabwriter"

	"github.com/spf13/cobra"
)

var listServicesSecrets bool

var listServicesCmd = &cobra.Command{
	Use:   "list-services <service>",
	Short: "List services",
	RunE: func(cmd *cobra.Command, args []string) error {
		s, err := getStore(cmd)
		if err != nil {
			return err
		}

		services, err := s.ListServices()
		if err != nil {
			return fmt.Errorf("Failed to list services: %v", err)
		}

		sort.Strings(services)
		fmt.Fprintln(os.Stdout, "Service")
		if len(services) > 0 {
			w := tabwriter.NewWriter(os.Stdout, 0, 8, 2, '\t', 0)
			for _, svc := range services {
				fmt.Fprintln(w, svc)
			}
			w.Flush()
		}
		return nil
	},
}

func init() {
	listServicesCmd.Flags().BoolVarP(&listServicesSecrets, "secrets", "s", false, "Include secret names in the list")
	rootCmd.AddCommand(listServicesCmd)
}
EOF

cat << 'EOF' > cmd/history.go
package cmd

import (
	"fmt"
	"os"
	"strings"
	"text/tabwriter"
	"time"

	"github.com/spf13/cobra"
)

var historyCmd = &cobra.Command{
	Use:   "history <service> <key>",
	Short: "View the history of a secret",
	Args:  cobra.ExactArgs(2),
	RunE: func(cmd *cobra.Command, args []string) error {
		service := args[0]
		key := strings.ToLower(args[1])

		s, err := getStore(cmd)
		if err != nil {
			return err
		}

		changes, err := s.History(service, key)
		if err != nil {
			return fmt.Errorf("Failed to get history: %v", err)
		}

		fmt.Fprintln(os.Stdout, "Event\tVersion\t\tDate\tUser")
		if len(changes) > 0 {
			w := tabwriter.NewWriter(os.Stdout, 0, 8, 2, '\t', 0)
			for _, ch := range changes {
				fmt.Fprintf(w, "%s\t%d\t\t%s\t%s\n", ch.Type, ch.Version, ch.Date.Format(time.RFC3339), ch.User)
			}
			w.Flush()
		}
		return nil
	},
}

func init() {
	rootCmd.AddCommand(historyCmd)
}
EOF

cat << 'EOF' > cmd/find.go
package cmd

import (
	"fmt"
	"os"
	"strings"
	"text/tabwriter"

	"github.com/spf13/cobra"
)

var findByValue bool

var findCmd = &cobra.Command{
	Use:   "find <secret name>",
	Short: "Find the given secret across all services",
	Args:  cobra.ExactArgs(1),
	RunE: func(cmd *cobra.Command, args []string) error {
		target := args[0]

		s, err := getStore(cmd)
		if err != nil {
			return err
		}

		services, err := s.ListServices()
		if err != nil {
			return fmt.Errorf("Failed to list services: %v", err)
		}

		if findByValue {
			fmt.Fprintln(os.Stdout, "Service\t\tKey")
			var matches [][2]string
			for _, svc := range services {
				secrets, err := s.List(svc)
				if err != nil {
					continue
				}
				for _, sec := range secrets {
					if sec.Value == target {
						matches = append(matches, [2]string{svc, sec.Key})
					}
				}
			}
			if len(matches) > 0 {
				w := tabwriter.NewWriter(os.Stdout, 0, 8, 2, '\t', 0)
				for _, m := range matches {
					fmt.Fprintf(w, "%s\t\t%s\n", m[0], m[1])
				}
				w.Flush()
			}
		} else {
			fmt.Fprintln(os.Stdout, "Service")
			targetLower := strings.ToLower(target)
			var matches []string
			for _, svc := range services {
				secrets, err := s.List(svc)
				if err != nil {
					continue
				}
				for _, sec := range secrets {
					if strings.ToLower(sec.Key) == targetLower {
						matches = append(matches, svc)
						break
					}
				}
			}
			if len(matches) > 0 {
				w := tabwriter.NewWriter(os.Stdout, 0, 8, 2, '\t', 0)
				for _, m := range matches {
					fmt.Fprintln(w, m)
				}
				w.Flush()
			}
		}
		return nil
	},
}

func init() {
	findCmd.Flags().BoolVarP(&findByValue, "by-value", "v", false, "Find parameters by value")
	rootCmd.AddCommand(findCmd)
}
EOF"}
